mapper.select:
SELECT COALESCE(SUM(final_amount), 0)
FROM krw_exchange
WHERE account_id = #{accountId}
  AND settlement_status = #{settlementStatus}
  AND final_at <= #{asOf}

SELECT YEAR(processed_at) AS purchaseYear,
       MONTH(processed_at) AS purchaseMonth,
       SUM(ABS(amount)) AS buyAmount
FROM domestic_order
WHERE account_id = #{accountId}
  AND side = #{side}
  AND status = #{orderStatus}
  AND processed_at <= #{asOf}
GROUP BY YEAR(processed_at), MONTH(processed_at)
ORDER BY YEAR(processed_at), MONTH(processed_at)
